Here is the root cause:
The commit 5e28b7b94408 introduced a logical error by placing the `idr_replace` call in the wrong location (inside the error path for `drm_prime_add_buf_handle`) and also had an unnecessary early exit check (`if (ret < 0) goto out_unlock;`) that caused the IDR replacement to be skipped in the normal flow, leading to inconsistent handle-to-object mapping and triggering a warning in `drm_prime_destroy_file_private`.

Here is the patch:

 int drm_gem_change_handle_ioctl(struct drm_device *dev, void *data,
 				struct drm_file *file_priv)
 {
 	struct drm_gem_change_handle *args = data;
 	struct drm_gem_object *obj, *idrobj;
 	int handle, ret;

 	if (!drm_core_check_feature(dev, DRIVER_GEM))
 		return -EOPNOTSUPP;

 	/* idr_alloc() limitation. */
 	if (args->new_handle > INT_MAX)
 		return -EINVAL;
 	handle = args->new_handle;

 	obj = drm_gem_object_lookup(file_priv, args->handle);
 	if (!obj)
 		return -ENOENT;

 	if (args->handle == handle) {
 		ret = 0;
 		goto out;
 	}

 	mutex_lock(&file_priv->prime.lock);

 	spin_lock(&file_priv->table_lock);

        /* When create_tail allocs an obj idr, it needs to first alloc as NULL,
 	* then later replace with the correct object. This is not necessary
 	* here, because the only operations that could race are drm_prime
 	* bookkeeping, and we hold the prime lock.
 	*/
 	ret = idr_alloc(&file_priv->object_idr, obj, handle, handle + 1,
 			GFP_NOWAIT);

        if (ret < 0) {
 	       spin_unlock(&file_priv->table_lock);
 	       goto out_unlock;
        }

        idrobj = idr_replace(&file_priv->object_idr, NULL, handle);
        if (idrobj != obj) {
 	       idr_replace(&file_priv->object_idr, idrobj, handle);
 	       idr_remove(&file_priv->object_idr, args->new_handle);
 	       spin_unlock(&file_priv->table_lock);
 	       ret = -ENOENT;
 	       goto out_unlock;
        }

 	spin_unlock(&file_priv->table_lock);

-	if (ret < 0)
-		goto out_unlock;
-
 	if (obj->dma_buf) {
 		ret = drm_prime_add_buf_handle(&file_priv->prime, obj->dma_buf,
 					       handle);
 		if (ret < 0) {
 			spin_lock(&file_priv->table_lock);
 			idr_remove(&file_priv->object_idr, handle);
-			idrobj = idr_replace(&file_priv->object_idr, obj, handle);
-			WARN_ON(idrobj != NULL);
 			spin_unlock(&file_priv->table_lock);
 			goto out_unlock;
 		}

 		drm_prime_remove_buf_handle(&file_priv->prime, args->handle);
 	}

 	ret = 0;

 	spin_lock(&file_priv->table_lock);
 	idr_remove(&file_priv->object_idr, args->handle);
+	idrobj = idr_replace(&file_priv->object_idr, obj, handle);
 	spin_unlock(&file_priv->table_lock);
+	WARN_ON(idrobj != NULL);

 out_unlock:
 	mutex_unlock(&file_priv->prime.lock);
 out:
 	drm_gem_object_put(obj);

 	return ret;
 }



